// GQ has no arithmetic over scores, so the 0.7/0.3 weighted sum can't be written.
// This approximates it with reciprocal rank fusion of the vector and BM25 arms.
query hybrid_scored($q: String, $v: Vector(3)) {
    match {
        $d: Doc
        match_text($d.body, $q)
    }
    return { $d.title, rrf(nearest($d.embedding, $v), bm25($d.body, $q)) as s }
    order { rrf(nearest($d.embedding, $v), bm25($d.body, $q)) }
    limit 10
}
